//==============================================================================
// FNC_REAL_TO_WORDS
// REAL (IEEE 754) -> two Modbus words
// Call: FNC_REAL_TO_WORDS(Real_value := x, High_word => ..., Low_word => ...);
//==============================================================================

Conversion.Real_value := Real_value;
Low_word  := Conversion.Word_value[0];
High_word := Conversion.Word_value[1];
FNC_REAL_TO_WORDS := TRUE;

//==============================================================================
// FNC_WORDS_TO_REAL
// Two Modbus words -> REAL (IEEE 754)
// ABCD device: High_word = lower address, CDAB device: Low_word = lower address
//==============================================================================

Conversion.Word_value[0] := Low_word;
Conversion.Word_value[1] := High_word;
FNC_WORDS_TO_REAL := Conversion.Real_value;

//==============================================================================
// GFC_COM_IN
// Modbus (GVL_MODBUS) -> GVL_COM : RTU equipment, SCADA FUXA, HMI
// Simple copies only, no conversion (conversions are done in the FBs)
//==============================================================================

//------------------------------------------------------------------------------
// COM : Modbus RTU, from equipment
//------------------------------------------------------------------------------
	//--- ADM100W_1
	GVL_COM.COM_ADM100W_1.COM_INPUT_IR    := GVL_MODBUS.ADM100W_InputRegisters;   // Input registers 0..87
	GVL_COM.COM_ADM100W_1.COM_INPUT_COILS := GVL_MODBUS.ADM100W_Alarms;           // Coils 0..9 (alarms)

	//--- DIP1500_1
	GVL_COM.COM_DIP1500_1.COM_INPUT_IR          := GVL_MODBUS.DIP1500_InputRegisters;     // Input registers 0x3001..0x3005
	GVL_COM.COM_DIP1500_1.COM_INPUT_HR_COUNTERS := GVL_MODBUS.DIP1500_Holding_Counters;   // Holding registers 0x4007..0x400A


//------------------------------------------------------------------------------
// SCADA FUXA : coils (FUXA 000001...)
//------------------------------------------------------------------------------
	//--- DOSENSOR_1
	GVL_COM.COM_DOSENSOR_1.SCADA_INPUT_CALIBRATION_HIGH := GVL_MODBUS.Coils_TCP_HMI[0].0;   // 1 | DO Calibration High
	GVL_COM.COM_DOSENSOR_1.SCADA_INPUT_CALIBRATION_LOW  := GVL_MODBUS.Coils_TCP_HMI[0].1;   // 2 | DO Calibration Low
	GVL_COM.COM_DOSENSOR_1.SCADA_INPUT_LOCAL_REQUEST    := GVL_MODBUS.Coils_TCP_HMI[0].7;   // 8 | DO Sensor Local Request
	GVL_COM.COM_DOSENSOR_1.SCADA_INPUT_AUTO_REQUEST     := GVL_MODBUS.Coils_TCP_HMI[1].0;   // 9 | DO Sensor Auto Request

	//--- DIP1500_1
	GVL_COM.COM_DIP1500_1.SCADA_INPUT_MOTOR_START_STOP   := GVL_MODBUS.Coils_TCP_HMI[0].2;   // 3 | DIP1500 Motor Start Stop
	GVL_COM.COM_DIP1500_1.SCADA_INPUT_MOTOR_DIRECTION    := GVL_MODBUS.Coils_TCP_HMI[0].3;   // 4 | DIP1500 Motor Direction
	GVL_COM.COM_DIP1500_1.SCADA_INPUT_FLASH_SAVE         := GVL_MODBUS.Coils_TCP_HMI[0].4;   // 5 | DIP1500 Flash Save
	GVL_COM.COM_DIP1500_1.SCADA_INPUT_OPERATION_MODE     := GVL_MODBUS.Coils_TCP_HMI[0].5;   // 6 | DIP1500 Operation Mode
	GVL_COM.COM_DIP1500_1.SCADA_INPUT_PARAM_WRITE_ENABLE := GVL_MODBUS.Coils_TCP_HMI[0].6;   // 7 | DIP1500 Parameter Write Enable
	GVL_COM.COM_DIP1500_1.SCADA_INPUT_LOCAL_REQUEST      := GVL_MODBUS.Coils_TCP_HMI[1].1;   // 10 | DIP1500 Local Request
	GVL_COM.COM_DIP1500_1.SCADA_INPUT_AUTO_REQUEST       := GVL_MODBUS.Coils_TCP_HMI[1].2;   // 11 | DIP1500 Auto Request

	//--- ADM100W_1
	GVL_COM.COM_ADM100W_1.SCADA_INPUT_LOCAL_REQUEST := GVL_MODBUS.Coils_TCP_HMI[1].3;   // 12 | ADM100W Local Request
	GVL_COM.COM_ADM100W_1.SCADA_INPUT_AUTO_REQUEST  := GVL_MODBUS.Coils_TCP_HMI[1].4;   // 13 | ADM100W Auto Request

	//--- UPI_LOCAL_FUXA
	GVL_COM.COM_UPI_LOCAL_FUXA.SCADA_INPUT_LOCAL_REQUEST := GVL_MODBUS.Coils_TCP_HMI[1].5;   // 14 | Global Local FUXA Request
	GVL_COM.COM_UPI_LOCAL_FUXA.SCADA_INPUT_AUTO_REQUEST  := GVL_MODBUS.Coils_TCP_HMI[1].6;   // 15 | Global Auto FUXA Request


//------------------------------------------------------------------------------
// SCADA FUXA : holding registers (FUXA 400001...), REAL = low word first (Float32MLE)
//------------------------------------------------------------------------------
	//--- DIP1500_1
	GVL_COM.COM_DIP1500_1.SCADA_INPUT_MOTOR_SPEED.Word_value[0]                                := GVL_MODBUS.Holding_register_TCP_HMI[0];    // 1 | DIP1500 Motor Speed (low word)
	GVL_COM.COM_DIP1500_1.SCADA_INPUT_MOTOR_SPEED.Word_value[1]                                := GVL_MODBUS.Holding_register_TCP_HMI[1];    // 2 | DIP1500 Motor Speed (high word)
	GVL_COM.COM_DIP1500_1.SCADA_INPUT_MAX_MOTOR_SPEED.Word_value[0]                            := GVL_MODBUS.Holding_register_TCP_HMI[2];    // 3 | DIP1500 Max Motor Speed (low word)
	GVL_COM.COM_DIP1500_1.SCADA_INPUT_MAX_MOTOR_SPEED.Word_value[1]                            := GVL_MODBUS.Holding_register_TCP_HMI[3];    // 4 | DIP1500 Max Motor Speed (high word)
	GVL_COM.COM_DIP1500_1.SCADA_INPUT_RUN_TIME_OR_VOLUME_SETPOINT.Word_value[0]                := GVL_MODBUS.Holding_register_TCP_HMI[4];    // 5 | DIP1500 Run Time Or Volume Setpoint (low word)
	GVL_COM.COM_DIP1500_1.SCADA_INPUT_RUN_TIME_OR_VOLUME_SETPOINT.Word_value[1]                := GVL_MODBUS.Holding_register_TCP_HMI[5];    // 6 | DIP1500 Run Time Or Volume Setpoint (high word)
	GVL_COM.COM_DIP1500_1.SCADA_INPUT_FLOW_RATE_OR_SPEED_CALIBRATION_COEFFICIENT.Word_value[0] := GVL_MODBUS.Holding_register_TCP_HMI[6];    // 7 | DIP1500 Flow Rate Or Speed Calibration Coefficient (low word)
	GVL_COM.COM_DIP1500_1.SCADA_INPUT_FLOW_RATE_OR_SPEED_CALIBRATION_COEFFICIENT.Word_value[1] := GVL_MODBUS.Holding_register_TCP_HMI[7];    // 8 | DIP1500 Flow Rate Or Speed Calibration Coefficient (high word)
	GVL_COM.COM_DIP1500_1.SCADA_INPUT_FOOT_SWITCH_INPUT_MODE                                   := GVL_MODBUS.Holding_register_TCP_HMI[8];    // 9 | DIP1500 Foot Switch Input Mode
	GVL_COM.COM_DIP1500_1.SCADA_INPUT_LIQUID_LEVEL_INPUT_MODE                                  := GVL_MODBUS.Holding_register_TCP_HMI[9];    // 10 | DIP1500 Liquid Level Input Mode
	GVL_COM.COM_DIP1500_1.SCADA_INPUT_STATE_OUTPUT_MODE                                        := GVL_MODBUS.Holding_register_TCP_HMI[10];   // 11 | DIP1500 State Output Mode
	GVL_COM.COM_DIP1500_1.SCADA_INPUT_COMMUNICATION_ADDRESS                                    := GVL_MODBUS.Holding_register_TCP_HMI[11];   // 12 | DIP1500 Communication Address
	GVL_COM.COM_DIP1500_1.SCADA_INPUT_BAUD_RATE_INDEX                                          := GVL_MODBUS.Holding_register_TCP_HMI[12];   // 13 | DIP1500 Baud Rate Index


//------------------------------------------------------------------------------
// HMI : coils (1001...)
//------------------------------------------------------------------------------
	//--- DOSENSOR_1
	GVL_COM.COM_DOSENSOR_1.HMI_INPUT_CALIBRATION_HIGH := GVL_MODBUS.Coils_TCP_HMI[125].0;   // 1001 | DO Calibration High
	GVL_COM.COM_DOSENSOR_1.HMI_INPUT_CALIBRATION_LOW  := GVL_MODBUS.Coils_TCP_HMI[125].1;   // 1002 | DO Calibration Low
	GVL_COM.COM_DOSENSOR_1.HMI_INPUT_LOCAL_REQUEST    := GVL_MODBUS.Coils_TCP_HMI[125].7;   // 1008 | DO Sensor Local Request
	GVL_COM.COM_DOSENSOR_1.HMI_INPUT_AUTO_REQUEST     := GVL_MODBUS.Coils_TCP_HMI[126].0;   // 1009 | DO Sensor Auto Request

	//--- DIP1500_1
	GVL_COM.COM_DIP1500_1.HMI_INPUT_MOTOR_START_STOP   := GVL_MODBUS.Coils_TCP_HMI[125].2;   // 1003 | DIP1500 Motor Start Stop
	GVL_COM.COM_DIP1500_1.HMI_INPUT_MOTOR_DIRECTION    := GVL_MODBUS.Coils_TCP_HMI[125].3;   // 1004 | DIP1500 Motor Direction
	GVL_COM.COM_DIP1500_1.HMI_INPUT_FLASH_SAVE         := GVL_MODBUS.Coils_TCP_HMI[125].4;   // 1005 | DIP1500 Flash Save
	GVL_COM.COM_DIP1500_1.HMI_INPUT_OPERATION_MODE     := GVL_MODBUS.Coils_TCP_HMI[125].5;   // 1006 | DIP1500 Operation Mode
	GVL_COM.COM_DIP1500_1.HMI_INPUT_PARAM_WRITE_ENABLE := GVL_MODBUS.Coils_TCP_HMI[125].6;   // 1007 | DIP1500 Parameter Write Enable
	GVL_COM.COM_DIP1500_1.HMI_INPUT_LOCAL_REQUEST      := GVL_MODBUS.Coils_TCP_HMI[126].1;   // 1010 | DIP1500 Local Request
	GVL_COM.COM_DIP1500_1.HMI_INPUT_AUTO_REQUEST       := GVL_MODBUS.Coils_TCP_HMI[126].2;   // 1011 | DIP1500 Auto Request

	//--- ADM100W_1
	GVL_COM.COM_ADM100W_1.HMI_INPUT_LOCAL_REQUEST := GVL_MODBUS.Coils_TCP_HMI[126].3;   // 1012 | ADM100W Local Request
	GVL_COM.COM_ADM100W_1.HMI_INPUT_AUTO_REQUEST  := GVL_MODBUS.Coils_TCP_HMI[126].4;   // 1013 | ADM100W Auto Request

	//--- UPI_LOCAL_HMI
	GVL_COM.COM_UPI_LOCAL_HMI.HMI_INPUT_LOCAL_REQUEST := GVL_MODBUS.Coils_TCP_HMI[126].5;   // 1014 | Global Local HMI Request
	GVL_COM.COM_UPI_LOCAL_HMI.HMI_INPUT_AUTO_REQUEST  := GVL_MODBUS.Coils_TCP_HMI[126].6;   // 1015 | Global Auto HMI Request


//------------------------------------------------------------------------------
// HMI : holding registers (1001...), REAL = low word first
//------------------------------------------------------------------------------
	//--- DIP1500_1
	GVL_COM.COM_DIP1500_1.HMI_INPUT_MOTOR_SPEED.Word_value[0]                                := GVL_MODBUS.Holding_register_TCP_HMI[1000];   // 1001 | DIP1500 Motor Speed (low word)
	GVL_COM.COM_DIP1500_1.HMI_INPUT_MOTOR_SPEED.Word_value[1]                                := GVL_MODBUS.Holding_register_TCP_HMI[1001];   // 1002 | DIP1500 Motor Speed (high word)
	GVL_COM.COM_DIP1500_1.HMI_INPUT_MAX_MOTOR_SPEED.Word_value[0]                            := GVL_MODBUS.Holding_register_TCP_HMI[1002];   // 1003 | DIP1500 Max Motor Speed (low word)
	GVL_COM.COM_DIP1500_1.HMI_INPUT_MAX_MOTOR_SPEED.Word_value[1]                            := GVL_MODBUS.Holding_register_TCP_HMI[1003];   // 1004 | DIP1500 Max Motor Speed (high word)
	GVL_COM.COM_DIP1500_1.HMI_INPUT_RUN_TIME_OR_VOLUME_SETPOINT.Word_value[0]                := GVL_MODBUS.Holding_register_TCP_HMI[1004];   // 1005 | DIP1500 Run Time Or Volume Setpoint (low word)
	GVL_COM.COM_DIP1500_1.HMI_INPUT_RUN_TIME_OR_VOLUME_SETPOINT.Word_value[1]                := GVL_MODBUS.Holding_register_TCP_HMI[1005];   // 1006 | DIP1500 Run Time Or Volume Setpoint (high word)
	GVL_COM.COM_DIP1500_1.HMI_INPUT_FLOW_RATE_OR_SPEED_CALIBRATION_COEFFICIENT.Word_value[0] := GVL_MODBUS.Holding_register_TCP_HMI[1006];   // 1007 | DIP1500 Flow Rate Or Speed Calibration Coefficient (low word)
	GVL_COM.COM_DIP1500_1.HMI_INPUT_FLOW_RATE_OR_SPEED_CALIBRATION_COEFFICIENT.Word_value[1] := GVL_MODBUS.Holding_register_TCP_HMI[1007];   // 1008 | DIP1500 Flow Rate Or Speed Calibration Coefficient (high word)
	GVL_COM.COM_DIP1500_1.HMI_INPUT_FOOT_SWITCH_INPUT_MODE                                   := GVL_MODBUS.Holding_register_TCP_HMI[1008];   // 1009 | DIP1500 Foot Switch Input Mode
	GVL_COM.COM_DIP1500_1.HMI_INPUT_LIQUID_LEVEL_INPUT_MODE                                  := GVL_MODBUS.Holding_register_TCP_HMI[1009];   // 1010 | DIP1500 Liquid Level Input Mode
	GVL_COM.COM_DIP1500_1.HMI_INPUT_STATE_OUTPUT_MODE                                        := GVL_MODBUS.Holding_register_TCP_HMI[1010];   // 1011 | DIP1500 State Output Mode
	GVL_COM.COM_DIP1500_1.HMI_INPUT_COMMUNICATION_ADDRESS                                    := GVL_MODBUS.Holding_register_TCP_HMI[1011];   // 1012 | DIP1500 Communication Address
	GVL_COM.COM_DIP1500_1.HMI_INPUT_BAUD_RATE_INDEX                                          := GVL_MODBUS.Holding_register_TCP_HMI[1012];   // 1013 | DIP1500 Baud Rate Index

GFC_COM_IN := TRUE;

//============================================================================== // GFC_COM_OUT // GVL_COM -> Modbus (GVL_MODBUS) : RTU equipment, SCADA FUXA, HMI // Simple copies only, no conversion (conversions are done in the FBs) //==============================================================================
//------------------------------------------------------------------------------ // COM : Modbus RTU, to equipment (write triggers are mapped directly in the slave I/O mapping) //------------------------------------------------------------------------------ //--- DIP1500_1 GVL_MODBUS.DIP1500_Coils := GVL_COM.COM_DIP1500_1.COM_OUTPUT_COILS; // Coils 0x0001..0x0004 GVL_MODBUS.DIP1500_Holding_Cmd := GVL_COM.COM_DIP1500_1.COM_OUTPUT_HR_CMD; // Holding registers 0x4001..0x4006 GVL_MODBUS.DIP1500_Holding_Config := GVL_COM.COM_DIP1500_1.COM_OUTPUT_HR_CONFIG; // Holding registers 0x400B..0x4011
//------------------------------------------------------------------------------ // SCADA FUXA : discrete inputs (FUXA 100001...) //------------------------------------------------------------------------------ //--- DOSENSOR_1 GVL_MODBUS.Discret_input_TCP_HMI[0].0 := GVL_COM.COM_DOSENSOR_1.SCADA_OUTPUT_FAULT; // 10001 | Do sensor fault GVL_MODBUS.Discret_input_TCP_HMI[0].1 := GVL_COM.COM_DOSENSOR_1.SCADA_OUTPUT_CALIBRATION_DONE; // 10002 | Do sensor calibration done GVL_MODBUS.Discret_input_TCP_HMI[1].4 := GVL_COM.COM_DOSENSOR_1.SCADA_OUTPUT_LOCAL_FUXA_ACTIVE; // 10013 | DO Sensor Local FUXA Active GVL_MODBUS.Discret_input_TCP_HMI[1].5 := GVL_COM.COM_DOSENSOR_1.SCADA_OUTPUT_LOCAL_HMI_ACTIVE; // 10014 | DO Sensor Local HMI Active
//--- ADM100W_1 GVL_MODBUS.Discret_input_TCP_HMI[0].2 := GVL_COM.COM_ADM100W_1.SCADA_OUTPUT_ALARM_1_STATUS; // 10003 | ADM100W Alarm 1 Status GVL_MODBUS.Discret_input_TCP_HMI[0].3 := GVL_COM.COM_ADM100W_1.SCADA_OUTPUT_ALARM_2_STATUS; // 10004 | ADM100W Alarm 2 Status GVL_MODBUS.Discret_input_TCP_HMI[0].4 := GVL_COM.COM_ADM100W_1.SCADA_OUTPUT_ALARM_3_STATUS; // 10005 | ADM100W Alarm 3 Status GVL_MODBUS.Discret_input_TCP_HMI[0].5 := GVL_COM.COM_ADM100W_1.SCADA_OUTPUT_ALARM_4_STATUS; // 10006 | ADM100W Alarm 4 Status GVL_MODBUS.Discret_input_TCP_HMI[0].6 := GVL_COM.COM_ADM100W_1.SCADA_OUTPUT_ALARM_5_STATUS; // 10007 | ADM100W Alarm 5 Status GVL_MODBUS.Discret_input_TCP_HMI[0].7 := GVL_COM.COM_ADM100W_1.SCADA_OUTPUT_ALARM_6_STATUS; // 10008 | ADM100W Alarm 6 Status GVL_MODBUS.Discret_input_TCP_HMI[1].0 := GVL_COM.COM_ADM100W_1.SCADA_OUTPUT_ALARM_7_STATUS; // 10009 | ADM100W Alarm 7 Status GVL_MODBUS.Discret_input_TCP_HMI[1].1 := GVL_COM.COM_ADM100W_1.SCADA_OUTPUT_ALARM_8_STATUS; // 10010 | ADM100W Alarm 8 Status GVL_MODBUS.Discret_input_TCP_HMI[1].2 := GVL_COM.COM_ADM100W_1.SCADA_OUTPUT_ALARM_9_STATUS; // 10011 | ADM100W Alarm 9 Status GVL_MODBUS.Discret_input_TCP_HMI[1].3 := GVL_COM.COM_ADM100W_1.SCADA_OUTPUT_ALARM_10_STATUS; // 10012 | ADM100W Alarm 10 Status GVL_MODBUS.Discret_input_TCP_HMI[2].0 := GVL_COM.COM_ADM100W_1.SCADA_OUTPUT_LOCAL_FUXA_ACTIVE; // 10017 | ADM100W Local FUXA Active GVL_MODBUS.Discret_input_TCP_HMI[2].1 := GVL_COM.COM_ADM100W_1.SCADA_OUTPUT_LOCAL_HMI_ACTIVE; // 10018 | ADM100W Local HMI Active
//--- DIP1500_1 GVL_MODBUS.Discret_input_TCP_HMI[1].6 := GVL_COM.COM_DIP1500_1.SCADA_OUTPUT_LOCAL_FUXA_ACTIVE; // 10015 | DIP1500 Local FUXA Active GVL_MODBUS.Discret_input_TCP_HMI[1].7 := GVL_COM.COM_DIP1500_1.SCADA_OUTPUT_LOCAL_HMI_ACTIVE; // 10016 | DIP1500 Local HMI Active
//--- UPI_LOCAL_FUXA GVL_MODBUS.Discret_input_TCP_HMI[2].2 := GVL_COM.COM_UPI_LOCAL_FUXA.SCADA_OUTPUT_LOCAL_ACTIVE; // 10019 | Global Local FUXA Active
//--- UPI_LOCAL_HMI GVL_MODBUS.Discret_input_TCP_HMI[2].3 := GVL_COM.COM_UPI_LOCAL_HMI.SCADA_OUTPUT_LOCAL_ACTIVE; // 10020 | Global Local HMI Active
