//==============================================================================
// FB_UPI_LOCAL_FUXA
// Global FUXA local mode for every equipment
// Set by the FUXA local request, reset by the FUXA auto request (pulse or maintained, auto wins)
// The equipment read this status through GFC_EXC_IN and report their own local status themselves
//==============================================================================

//------------------------------------------------------------------------------
// 1. INPUTS
//------------------------------------------------------------------------------
	INTERN.LOCAL_REQUEST := COM.SCADA_INPUT_LOCAL_REQUEST;
	INTERN.AUTO_REQUEST  := COM.SCADA_INPUT_AUTO_REQUEST;


//------------------------------------------------------------------------------
// 2. PROCESSING
//------------------------------------------------------------------------------
	IF INTERN.LOCAL_REQUEST THEN
		INTERN.LOCAL_ACTIVE := TRUE;
	END_IF
	IF INTERN.AUTO_REQUEST THEN
		INTERN.LOCAL_ACTIVE := FALSE;
	END_IF


//------------------------------------------------------------------------------
// 3. OUTPUTS
//------------------------------------------------------------------------------
	//--- EXC : to every equipment (through GFC_EXC_IN)
	EXC.UPI_OUTPUT_LOCAL_ACTIVE := INTERN.LOCAL_ACTIVE;

	//--- COM : status
	COM.SCADA_OUTPUT_LOCAL_ACTIVE := INTERN.LOCAL_ACTIVE;

//==============================================================================
// FB_UPI_LOCAL_HMI
// Global HMI local mode for every equipment
// Set by the HMI local request, reset by the HMI auto request (pulse or maintained, auto wins)
// The equipment read this status through GFC_EXC_IN and report their own local status themselves
//==============================================================================

//------------------------------------------------------------------------------
// 1. INPUTS
//------------------------------------------------------------------------------
	INTERN.LOCAL_REQUEST := COM.HMI_INPUT_LOCAL_REQUEST;
	INTERN.AUTO_REQUEST  := COM.HMI_INPUT_AUTO_REQUEST;


//------------------------------------------------------------------------------
// 2. PROCESSING
//------------------------------------------------------------------------------
	IF INTERN.LOCAL_REQUEST THEN
		INTERN.LOCAL_ACTIVE := TRUE;
	END_IF
	IF INTERN.AUTO_REQUEST THEN
		INTERN.LOCAL_ACTIVE := FALSE;
	END_IF


//------------------------------------------------------------------------------
// 3. OUTPUTS
//------------------------------------------------------------------------------
	//--- EXC : to every equipment (through GFC_EXC_IN)
	EXC.UPI_OUTPUT_LOCAL_ACTIVE := INTERN.LOCAL_ACTIVE;

	//--- COM : status
	COM.HMI_OUTPUT_LOCAL_ACTIVE   := INTERN.LOCAL_ACTIVE;
	COM.SCADA_OUTPUT_LOCAL_ACTIVE := INTERN.LOCAL_ACTIVE;   // also reported to FUXA

//==============================================================================
// GFB_INST
// Calls every equipment instance
// One block per equipment, all interfaces connected
//==============================================================================

//--- ADM100W_1 : Trumeter ADM100W power meter
FB_ADM100W_1(
	PA  := GVL_PA.PA_ADM100W_1,
	COM := GVL_COM.COM_ADM100W_1,
	EXC := GVL_EXC.EXC_ADM100W_1,
	IO  := GVL_IO.IO_ADM100W_1);

//--- DOSENSOR_1 : Dissolved oxygen sensor
FB_DOSENSOR_1(
	PA  := GVL_PA.PA_DOSENSOR_1,
	COM := GVL_COM.COM_DOSENSOR_1,
	EXC := GVL_EXC.EXC_DOSENSOR_1,
	IO  := GVL_IO.IO_DOSENSOR_1);

//--- DIP1500_1 : Kamoer DIP1500 peristaltic pump
FB_DIP1500_1(
	PA  := GVL_PA.PA_DIP1500_1,
	COM := GVL_COM.COM_DIP1500_1,
	EXC := GVL_EXC.EXC_DIP1500_1,
	IO  := GVL_IO.IO_DIP1500_1);

//==============================================================================
// GFB_UPI
// Calls every functional unit (UPI)
// Runs before GFB_INST, results go to the equipment through GFC_EXC_IN
//==============================================================================

//--- UPI_LOCAL_FUXA : Global FUXA local mode
