	COM.SCADA_OUTPUT_ALARM_10_STATUS := INTERN.ALARM_10;
	COM.HMI_OUTPUT_ALARM_10_STATUS   := INTERN.ALARM_10;
	COM.WEBVISU_OUTPUT_ALARM_10_STATUS   := INTERN.ALARM_10;

	//--- COM : measures to SCADA, HMI and WEBVISU
